import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import inspect

async def async_dep():
    return {"foo": "bar"}

def wrapper(func):
    @functools.wraps(func)
    def wrapped():
        return func()
    return wrapped

wrapped_async_dep = wrapper(async_dep)

app = FastAPI()

@app.get("/")
async def root(dep = Depends(wrapped_async_dep)):
    return dep

client = TestClient(app)

def test_wrapped_async_dep():
    print(f"Is coroutine function: {inspect.iscoroutinefunction(wrapped_async_dep)}")
    response = client.get("/")
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

if __name__ == "__main__":
    try:
        test_wrapped_async_dep()
        print("Test passed!")
